-- End-of-shift checklists: what an employee must do before leaving, per kitchen post and per role. Editable in Administration.
CREATE TABLE checklists (
  id        INTEGER PRIMARY KEY AUTOINCREMENT,
  client_id INTEGER NOT NULL REFERENCES clients(id) ON DELETE CASCADE,
  kind      TEXT NOT NULL CHECK (kind IN ('post', 'role')),
  target_id INTEGER NOT NULL,
  UNIQUE (client_id, kind, target_id)
);
CREATE TABLE checklist_items (
  id           INTEGER PRIMARY KEY AUTOINCREMENT,
  checklist_id INTEGER NOT NULL REFERENCES checklists(id) ON DELETE CASCADE,
  position     INTEGER NOT NULL DEFAULT 0,
  text_fr      TEXT NOT NULL,
  text_en      TEXT,
  last_out     INTEGER NOT NULL DEFAULT 0   -- only for the last person of the department to leave (e.g. the last driver)
);
CREATE INDEX idx_checklist_items ON checklist_items (checklist_id, position);
-- Kitchen posts picked by the employee for a shift (role lists apply automatically).
CREATE TABLE shift_checklists (
  shift_id     INTEGER NOT NULL REFERENCES shifts(id) ON DELETE CASCADE,
  checklist_id INTEGER NOT NULL REFERENCES checklists(id) ON DELETE CASCADE,
  PRIMARY KEY (shift_id, checklist_id)
);
CREATE TABLE shift_checklist_done (
  shift_id INTEGER NOT NULL REFERENCES shifts(id) ON DELETE CASCADE,
  item_id  INTEGER NOT NULL REFERENCES checklist_items(id) ON DELETE CASCADE,
  done_by  INTEGER REFERENCES staff(id) ON DELETE SET NULL,
  done_at  INTEGER NOT NULL,
  PRIMARY KEY (shift_id, item_id)
);

